"""Matched fee/public/none/voucher scenarios; real balances, capacity and closure."""
from test_mobile_rendering import ROOT,html
from playwright.sync_api import sync_playwright
import json,hashlib
source=(ROOT/'assets/game.js').read_text();sha=hashlib.sha256(source.encode()).hexdigest()
probe=r'''
window.__privateFixture=(kind='school',vouchers=0)=>{__townTest.reset('settlement',42);G.autoBuild=false;G.policy.privateServices=0;G.policy.educationBudget=0;G.policy.defenseBudget=0;G.policy.aidBudget=0;G.policy.energyAidBudget=0;G.policy.serviceVoucherBudget=vouchers;G.civicTraining=[];for(const p of G.people)if(p.age>=18&&p.age<=60)p.skill=.6;
 const b=G.buildings.find(b=>b.kind===kind),f=createFirm(kind,b.x,b.y,true,()=>b);G.region-=f.cash;f.privateService=kind;f.serviceFee=kind==='school'?3:.8;f.wage=36;f.jobs=2;b.title={kind:'firm',id:f.id};const poor=G.households.find(h=>h.people.length>=2&&sharesRoadNetwork(readBuild(h.home),b));G.region+=poor.cash;poor.cash=0;if(kind==='school'){const learner=G.people[poor.people[0]];learner.age=30;learner.skill=.6;G.civicTraining=[{person:learner.id,days:10,started:G.day}];}for(const id of poor.people){const p=G.people[id];if(p.job>=0)G.firms[p.job].workers=G.firms[p.job].workers.filter(x=>x!==id);p.job=-1;p.searchAfter=G.day+10;}assignJobs();invalidateRoads(false);return{firm:f.id,poor:poor.id,total:totalMoney()}};
window.__privateSample=(id,poor)=>{const f=G.firms[id];return{day:G.day,staff:f.workers.length,clients:f.clientsToday,capacity:f.serviceCapacity,tuition:f.privateReceipts,vouchers:f.privateVouchers,total:totalMoney(),schoolPublicFacilities:G.buildings.filter(b=>b.kind==='school'&&isPublicFacility(b)).length,publicSchoolCoverage:G.serviceProvision?.school?.coverage||0,poorCoverage:localCivicCoverage('school',poor),poorPrivate:G.privateServiceProvision?.school?.[poor]||0,pupils:G.privateServiceProvision?.pupils||0,learning:G.privateTrainingCompletions||0,response:privateFireResponse(readBuild(G.households[poor].home)),valid:validateTown()}};
window.__privateClose=id=>{liquidateFirm(G.firms[id],'test controlled provider insolvency');};
window.__privateReopen=id=>{G.policy.privateServices=1;return seekPrivateServiceInvestment(G.firms[id].privateService)};
window.__privateZeroFee=()=>{G.policy.privateTuitionCap=0};
window.__publicCompare=budget=>{__townTest.reset('settlement',42);G.autoBuild=false;G.policy.privateServices=0;G.policy.educationBudget=budget;for(const p of G.people)if(p.age>=18&&p.age<=60)p.skill=.6;const total=totalMoney();__townTest.step(2);return{budget,publicCoverage:G.serviceProvision.school.coverage,privatePupils:G.privateServiceProvision?.pupils||0,cashDrift:totalMoney()-total,valid:validateTown()}};
window.__privateOnce=()=>{const t=totalMoney(),paid=G.privateServiceProvision?.tuition;privateServiceDay();return{cash:totalMoney()-t,paidUnchanged:G.privateServiceProvision?.tuition===paid}};
'''
rows=[]
with sync_playwright() as pw:
 b=pw.chromium.launch(executable_path='/usr/bin/chromium',args=['--no-sandbox']);p=b.new_page();errors=[];p.on('pageerror',lambda e:errors.append(str(e)));p.set_content(html);p.add_script_tag(content=source.replace('// SOURCE: 99-instrumentation.js',probe+'\n// SOURCE: 99-instrumentation.js'));p.locator('#newTown').click();p.locator('#pause').click()
 for budget in [0,180]:
  control=p.evaluate('b=>__publicCompare(b)',budget);assert control['privatePupils']==0 and abs(control['cashDrift'])<.001 and control['valid']['ok'];assert control['publicCoverage']==0 if budget==0 else control['publicCoverage']>0;rows.append({'matchedPublicControl':True,**control})
 for vouchers in [0,100]:
  f=p.evaluate('v=>__privateFixture("school",v)',vouchers);p.evaluate('__townTest.step(1)');r=p.evaluate('o=>__privateSample(o.firm,o.poor)',f);assert r['valid']['ok'] and abs(r['total']-f['total'])<.001,r;assert r['schoolPublicFacilities']==0 and r['publicSchoolCoverage']==0;assert r['clients']>0 and r['capacity']<=r['staff']*16 and r['clients']<=r['capacity']+.001,r;assert r['poorPrivate']==0 if vouchers==0 else r['poorPrivate']>0,r;assert p.evaluate('__privateOnce()')=={'cash':0,'paidUnchanged':True};rows.append({'voucherBudget':vouchers,**r});saved=p.evaluate('__townTest.save()');assert p.evaluate('s=>__townTest.load(s)',saved)
 # New matched fixture for sustained paid teaching, not a free skill grant.
 f=p.evaluate('__privateFixture("school",100)');p.evaluate('__townTest.step(190)');r=p.evaluate('o=>__privateSample(o.firm,o.poor)',f);assert r['learning']>0 and r['valid']['ok'],r;rows.append({'longTerm':True,**r});p.evaluate('id=>__privateClose(id)',f['firm']);p.evaluate('__townTest.step(1)');r=p.evaluate('o=>__privateSample(o.firm,o.poor)',f);assert r['capacity']==0 and r['clients']==0 and r['valid']['ok'],r
 p.evaluate('__townTest.step(125)');message=p.evaluate('id=>__privateReopen(id)',f['firm']);assert 'recapitalized' not in message,message;p.evaluate('__townTest.step(31)');message=p.evaluate('id=>__privateReopen(id)',f['firm']);assert 'recapitalized' in message,message;p.evaluate('__townTest.step(2)');assert p.evaluate('__townTest.validate().ok');rows.append({'recapitalization':message,'snapshot':p.evaluate('o=>__privateSample(o.firm,o.poor)',f)});
 f=p.evaluate('__privateFixture("school",0)');p.evaluate('__privateZeroFee()');p.evaluate('__townTest.step(600)');g=json.loads(p.evaluate('__townTest.save()'));assert g['firms'][f['firm']].get('closed',False),g['firms'][f['firm']];assert abs(p.evaluate('__townTest.get().total')-f['total'])<.001;rows.append({'zeroFeeExit':True,'day':g['day'],'closed':g['firms'][f['firm']]['closed']});
 f=p.evaluate('__privateFixture("fire",100)');p.evaluate('__townTest.step(1)');r=p.evaluate('o=>__privateSample(o.firm,o.poor)',f);assert r['clients']>0 and r['response']>0 and r['valid']['ok'],r;assert abs(r['total']-f['total'])<.001;rows.append({'fire':True,**r});bad=json.loads(p.evaluate('__townTest.save()'));bad['firms'][f['firm']]['serviceFee']=-1;assert not p.evaluate('s=>__townTest.load(s)',json.dumps(bad));assert not errors,errors;b.close()
assert hashlib.sha256((ROOT/'assets/game.js').read_bytes()).hexdigest()==sha
out=ROOT/'reports/development-8.0';out.mkdir(exist_ok=True);(out/'private-services.json').write_text(json.dumps({'source_sha256':sha,'controlledFixtures':True,'rows':rows,'errors':errors},indent=2)+'\n');print('PASS private fees/staffed capacity/poor affordability/targeted vouchers/190day learning/closure/fire spillover/exact-once/conservation/archive checks',rows)
